            , GENERATE_UUID() AS mf_internal_uuid
          FROM sma_10008_cte
        ) subq_16
        ON
          (
            subq_14.session = subq_16.session
          ) AND (
            (
              subq_14.metric_time__day <= subq_16.metric_time__day
            ) AND (
              subq_14.metric_time__day > DATE_SUB(CAST(subq_16.metric_time__day AS DATETIME), INTERVAL 2 day)
            )
          )
      ) subq_17
      GROUP BY
        metric_time__month
    ) subq_21
    ON
      subq_10.metric_time__month = subq_21.metric_time__month
    GROUP BY
      metric_time__month
  ) subq_22
  ON
    subq_5.metric_time__month = subq_22.metric_time__month
  FULL OUTER JOIN (
    -- Re-aggregate Metric via Group By
    SELECT
      metric_time__month
      , engaged_customers_28d
    FROM (
      -- Window Function for Metric Re-aggregation
      SELECT
        metric_time__month
        , FIRST_VALUE(engaged_customers_28d) OVER (
          PARTITION BY metric_time__month
          ORDER BY metric_time__day
          ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
        ) AS engaged_customers_28d
      FROM (
        -- Join Self Over Time Range
        -- Select: ['__acting_customers', 'metric_time__month', 'metric_time__day']
        -- Select: ['__acting_customers', 'metric_time__month', 'metric_time__day']
        -- Aggregate Inputs for Simple Metrics
        -- Compute Metrics via Expressions
        -- Compute Metrics via Expressions
        SELECT
          subq_26.date_day AS metric_time__day
          , TIMESTAMP_TRUNC(subq_26.date_day, month) AS metric_time__month
          , COUNT(DISTINCT sma_10008_cte.__acting_customers) AS engaged_customers_28d
        FROM {{ ref('metricflow_time_spine') }} subq_26
        INNER JOIN
          sma_10008_cte
        ON
          (
            sma_10008_cte.metric_time__day <= subq_26.date_day
          ) AND (
            sma_10008_cte.metric_time__day > DATE_SUB(CAST(subq_26.date_day AS DATETIME), INTERVAL 28 day)
          )
        GROUP BY
          metric_time__day
          , metric_time__month
      ) subq_32
    ) subq_33
    GROUP BY
      metric_time__month
      , engaged_customers_28d
  ) subq_34
  ON
    COALESCE(subq_5.metric_time__month, subq_22.metric_time__month) = subq_34.metric_time__month
  FULL OUTER JOIN (
    -- Re-aggregate Metric via Group By
    SELECT
      metric_time__month
      , engaged_customers_7d
    FROM (
      -- Window Function for Metric Re-aggregation
      SELECT
        metric_time__month
        , FIRST_VALUE(engaged_customers_7d) OVER (
          PARTITION BY metric_time__month
          ORDER BY metric_time__day
          ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
        ) AS engaged_customers_7d
      FROM (
        -- Join Self Over Time Range
        -- Select: ['__acting_customers', 'metric_time__month', 'metric_time__day']
        -- Select: ['__acting_customers', 'metric_time__month', 'metric_time__day']
        -- Aggregate Inputs for Simple Metrics
        -- Compute Metrics via Expressions
        -- Compute Metrics via Expressions
        SELECT
          subq_37.date_day AS metric_time__day
          , TIMESTAMP_TRUNC(subq_37.date_day, month) AS metric_time__month
          , COUNT(DISTINCT sma_10008_cte.__acting_customers) AS engaged_customers_7d
        FROM {{ ref('metricflow_time_spine') }} subq_37
        INNER JOIN
          sma_10008_cte
        ON
          (
            sma_10008_cte.metric_time__day <= subq_37.date_day
          ) AND (
            sma_10008_cte.metric_time__day > DATE_SUB(CAST(subq_37.date_day AS DATETIME), INTERVAL 7 day)
          )
        GROUP BY
          metric_time__day
          , metric_time__month
      ) subq_43
    ) subq_44
    GROUP BY
      metric_time__month
      , engaged_customers_7d
  ) subq_45
  ON
    COALESCE(subq_5.metric_time__month, subq_22.metric_time__month, subq_34.metric_time__month) = subq_45.metric_time__month
  FULL OUTER JOIN (
    -- Constrain Output with WHERE
    -- Select: ['__site_sessions', 'metric_time__month']
    -- Aggregate Inputs for Simple Metrics
    -- Compute Metrics via Expressions
    SELECT
      metric_time__month
      , COUNT(DISTINCT site_sessions) AS site_sessions
    FROM (
      -- Read From CTE For node_id=sma_10008
      -- Select: ['__site_sessions', 'customer_action__action_type', 'metric_time__month']
      SELECT
        metric_time__month
        , customer_action__action_type
        , __site_sessions AS site_sessions
      FROM sma_10008_cte
    ) subq_47
    WHERE customer_action__action_type = 'page_view'
    GROUP BY
      metric_time__month
  ) subq_51
  ON
    COALESCE(subq_5.metric_time__month, subq_22.metric_time__month, subq_34.metric_time__month, subq_45.metric_time__month) = subq_51.metric_time__month
  FULL OUTER JOIN (
    -- Combine Aggregated Outputs
    SELECT
      COALESCE(subq_56.metric_time__month, subq_67.metric_time__month) AS metric_time__month
      , MAX(subq_56.__site_sessions) AS __site_sessions
      , MAX(subq_67.__cart_sessions) AS __cart_sessions
    FROM (
      -- Constrain Output with WHERE
      -- Select: ['__site_sessions', 'metric_time__month']
      -- Aggregate Inputs for Simple Metrics
      SELECT
        metric_time__month
        , COUNT(DISTINCT site_sessions) AS __site_sessions
      FROM (
        -- Read From CTE For node_id=sma_10008
        -- Select: ['__site_sessions', 'customer_action__action_type', 'metric_time__month']
        SELECT
          metric_time__month
          , customer_action__action_type
          , __site_sessions AS site_sessions
        FROM sma_10008_cte
      ) subq_53
      WHERE customer_action__action_type = 'page_view'
      GROUP BY
        metric_time__month
    ) subq_56
    FULL OUTER JOIN (
      -- Find conversions for session within the range of 2 day
      -- Select: ['__cart_sessions', 'metric_time__month']
      -- Select: ['__cart_sessions', 'metric_time__month']
      -- Aggregate Inputs for Simple Metrics
      SELECT
        metric_time__month
        , COUNT(DISTINCT __cart_sessions) AS __cart_sessions
      FROM (
        -- Dedupe the fanout with mf_internal_uuid in the conversion data set
        SELECT DISTINCT
          FIRST_VALUE(subq_60.__site_sessions) OVER (
            PARTITION BY
              subq_62.session
              , subq_62.metric_time__day
              , subq_62.mf_internal_uuid
            ORDER BY subq_60.metric_time__day DESC
            ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
          ) AS __site_sessions
          , FIRST_VALUE(subq_60.customer_action__action_type) OVER (
            PARTITION BY
              subq_62.session
              , subq_62.metric_time__day
              , subq_62.mf_internal_uuid
            ORDER BY subq_60.metric_time__day DESC
            ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
          ) AS customer_action__action_type
          , FIRST_VALUE(subq_60.metric_time__day) OVER (
            PARTITION BY
              subq_62.session
              , subq_62.metric_time__day
              , subq_62.mf_internal_uuid
            ORDER BY subq_60.metric_time__day DESC
            ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
          ) AS metric_time__day
          , FIRST_VALUE(subq_60.metric_time__month) OVER (
            PARTITION BY
              subq_62.session
              , subq_62.metric_time__day
              , subq_62.mf_internal_uuid
            ORDER BY subq_60.metric_time__day DESC
            ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
          ) AS metric_time__month
          , FIRST_VALUE(subq_60.session) OVER (
            PARTITION BY
              subq_62.session
              , subq_62.metric_time__day
              , subq_62.mf_internal_uuid
            ORDER BY subq_60.metric_time__day DESC
            ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
          ) AS session
          , subq_62.mf_internal_uuid AS mf_internal_uuid
          , subq_62.__cart_sessions AS __cart_sessions
        FROM (
          -- Constrain Output with WHERE
          -- Select: ['__site_sessions', 'customer_action__action_type', 'metric_time__day', 'metric_time__month', 'session']
          SELECT
            metric_time__day
            , metric_time__month
            , session
            , customer_action__action_type
            , site_sessions AS __site_sessions
          FROM (
            -- Read From CTE For node_id=sma_10008
            -- Select: ['__site_sessions', 'customer_action__action_type', 'metric_time__day', 'metric_time__month', 'session']
            SELECT
              metric_time__day
              , metric_time__month
              , session
              , customer_action__action_type
              , __site_sessions AS site_sessions
            FROM sma_10008_cte
          ) subq_58
          WHERE customer_action__action_type = 'page_view'
        ) subq_60
        INNER JOIN (
          -- Read From CTE For node_id=sma_10008
          -- Add column with generated UUID
          SELECT
            metric_time__day
            , session
            , __cart_sessions
            , GENERATE_UUID() AS mf_internal_uuid
          FROM sma_10008_cte
        ) subq_62
        ON
          (
            subq_60.session = subq_62.session
          ) AND (
            (
              subq_60.metric_time__day <= subq_62.metric_time__day
            ) AND (
              subq_60.metric_time__day > DATE_SUB(CAST(subq_62.metric_time__day AS DATETIME), INTERVAL 2 day)
            )
          )
      ) subq_63
      GROUP BY
        metric_time__month
    ) subq_67
    ON
      subq_56.metric_time__month = subq_67.metric_time__month
    GROUP BY
      metric_time__month
  ) subq_68
  ON
    COALESCE(subq_5.metric_time__month, subq_22.metric_time__month, subq_34.metric_time__month, subq_45.metric_time__month, subq_51.metric_time__month) = subq_68.metric_time__month
  GROUP BY
    metric_time__month
) as metricflow
